/**
 * Marks this region as quarantined and stops it from being scheduled.
 *
 * <p>Safe to call from the watchdog thread or from the region's own tick thread.</p>
 */
public void markQuarantined(final String reason) {
    if (this.quarantined) {
        return;
    }
    this.quarantineReason = reason;
    this.quarantined = true;
    // Stop any future tick / task drain for this handle.
    this.tickHandle.markNonSchedulable();
}

/**
 * Clears a quarantine and puts the region back on the scheduler.
 *
 * <p>Because {@code markNonSchedulable()} poisons the current handle, the clean way back is to
 * swap in a fresh handle and register it. Must only be called from the global region (i.e. the
 * console) so that the region is guaranteed not to be ticking while we mutate its handle.</p>
 */
public void recoverFromQuarantine() {
    final io.papermc.paper.threadedregions.TickRegionScheduler scheduler =
        io.papermc.paper.threadedregions.TickRegions.getScheduler();
    this.quarantined = false;
    this.quarantineReason = null;
    final ConcreteRegionTickHandle fresh = this.tickHandle.copy();
    fresh.checkInitialSchedule();
    this.tickHandle = fresh;
    scheduler.scheduleRegion(fresh);
}
