// MineX start - non-blocking protocol switch
// Upstream does future.syncUninterruptibly() here. On Folia the caller is the GLOBAL REGION
// thread (handleLoginAcknowledgement runs there via PacketUtils.ensureRunningOnSameThread ->
// RegionizedServer.schedulePacket). Parking that thread on a Netty channel promise freezes
// logins, keepalives and packet dispatch for EVERY player until the promise resolves - this is
// the mechanism behind the 20-60s "Global region has not responded" incidents (the watchdog
// stack was exactly this call).
//
// The promise only completes when the connection's event-loop thread runs. If that thread is
// busy or the client is lossy, we block the whole server on one player's socket.
//
// The ordered pipeline reconfigure does not actually require the caller to wait: the
// configuration tasks are written to the channel and executed in order by the event loop, and
// any packet subsequently written through this same Connection is written to the same channel,
// so ordering is preserved without a synchronous handshake. We therefore only wait when we are
// already ON the event loop (where blocking is harmless because the promise is resolved by the
// very thread making progress), and otherwise let it complete asynchronously.
if (future.channel().eventLoop().inEventLoop()) {
    try {
        future.syncUninterruptibly();
    } catch (final Exception ex) {
        if (ex instanceof ClosedChannelException) {
            LOGGER.info("Connection closed during protocol change");
        } else {
            throw ex;
        }
    }
    return;
}

future.addListener((ChannelFutureListener)completed -> {
    if (!completed.isSuccess()) {
        final Throwable cause = completed.cause();
        if (cause instanceof ClosedChannelException) {
            LOGGER.debug("Connection closed during protocol change");
        } else if (cause != null) {
            LOGGER.debug("Protocol change failed asynchronously for connection", cause);
        }
    }
});
// MineX end - non-blocking protocol switch

